GaussianProcessRegressor(
        kernel=kernel,
        alpha=float(
            specification[
                "numerical_jitter"
            ]
        ),
        optimizer=specification[
            "optimizer"
        ],
        n_restarts_optimizer=int(
            specification[
                "optimizer_restarts"
            ]
        ),
        normalize_y=bool(
            specification[
                "normalise_training_target"
            ]
        ),
        copy_X_train=True,
        random_state=int(
            specification[
                "random_seed"
            ]
        ),
    )

Matern(
            length_scale=float(
                kernel_specification[
                    "initial_length_scale"
                ]
            ),
            length_scale_bounds=tuple(
                kernel_specification[
                    "length_scale_bounds"
                ]
            ),
            nu=float(
                kernel_specification["nu"]
            ),
        )
